-- Table: hrm_statutory_contribution_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_statutory_contribution_detail (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    contribution_id     BIGINT NOT NULL REFERENCES hrm_statutory_contribution(id) ON DELETE CASCADE,
    line_number         INTEGER NOT NULL CHECK (line_number > 0),
    employee_id         BIGINT NOT NULL REFERENCES masterdata_employee(id),
    contribution_type   VARCHAR(30) NOT NULL
                        CHECK (contribution_type IN ('bpjs_kesehatan', 'bpjs_tk', 'pph21', 'other')),
    employee_amount     NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (employee_amount >= 0),
    employer_amount     NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (employer_amount >= 0),
    total_amount        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_amount >= 0),
    due_date            DATE,
    paid_amount         NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (paid_amount >= 0),
    notes               TEXT,
    UNIQUE (contribution_id, line_number)
);
